/*
 * Personal Finance Hub — a dark, fintech-style personal finance app: overview
 * (balance, investments, transactions, statistics, transfers, portfolio),
 * cards and spending analytics. Built from standard visuals on a 24-column
 * grid. Jordan Ellis, the companies and all figures are fictional.
 */

const eur: NumberFormat = { kind: 'currency', currency: 'EUR', decimals: 2 };
const eurCompact: NumberFormat = { kind: 'currency', currency: 'EUR', compact: true, decimals: 1 };
const eurWhole: NumberFormat = { kind: 'currency', currency: 'EUR', decimals: 0 };

/** Hero balance panel: deep ember fading into the page (light text keeps full contrast). */
const EMBER: ComponentStyle = { background: '#3B1A12', backgroundTo: '#141416', showBorder: false };
/** The selected card: accent outline with a soft glow. */
const SELECTED: ComponentStyle = { borderColor: '#F26430', showBorder: true, glow: true };

/** Icon in the corner and the change shown compactly beside the value. */
function withIcon(c: DashboardComponent, icon: IconName, inline = true): DashboardComponent {
  if (c.type !== 'kpi') return c;
  return { ...c, config: { ...c.config, icon, ...(inline ? { trendStyle: 'inline' as const } : {}) } };
}

function cardImage(id: string, box: GridBox, src: string, alt: string): DashboardComponent {
  return visual('image', id, box, {
    title: '',
    data: { src, alt },
    config: { fit: 'contain', placeholderLabel: 'Add your card image' },
    // A normal tile: the artwork's background is the theme surface colour, so the card sits seamlessly in its panel.
    style: { padding: 0 },
  });
}

function heading(id: string, box: GridBox, text: string, variant: 'heading' | 'subheading' = 'heading'): DashboardComponent {
  return visual('text', id, box, {
    data: { text },
    config: { variant, verticalAlign: 'bottom' },
    style: { transparent: true, padding: 4 },
  });
}

function caption(id: string, box: GridBox, text: string): DashboardComponent {
  return visual('text', id, box, {
    data: { text },
    config: { variant: 'caption', verticalAlign: 'top', emphasis: 'muted' },
    style: { transparent: true, padding: 4 },
  });
}

const DAYS = ['Nov 1', 'Nov 2', 'Nov 3', 'Nov 4', 'Nov 5', 'Nov 6', 'Nov 7'];
const income = trend({ length: 12, start: 5_600, growth: 0.09, noise: 0.03, seed: 1101 });
const expenses = trend({ length: 12, start: 3_900, growth: 0.05, noise: 0.06, seasonality: 0.06, seed: 1102 });
const savings = income.map((v, i) => v - expenses[i]!);

const cards = [
  { id: 'ember', src: cardEmber, name: 'Ember Debit', status: 'Active', balance: 21_480.4, number: '•••• 4821', holder: 'Jordan Ellis', expires: '08/29', alt: 'Ember debit card ending 4821' },
  { id: 'graphite', src: cardGraphite, name: 'Graphite Credit', status: 'Active', balance: 8_215.75, number: '•••• 7305', holder: 'Jordan Ellis', expires: '03/28', alt: 'Graphite credit card ending 7305' },
  { id: 'ocean', src: cardOcean, name: 'Ocean Travel', status: 'Frozen', balance: 3_092.1, number: '•••• 1946', holder: 'Sam Ellis', expires: '11/27', alt: 'Ocean travel card ending 1946' },
];

function cardRow(c: (typeof cards)[number], y: number): DashboardComponent[] {
  return [
    cardImage(`pfh-c-${c.id}-img`, [0, y, 5, 5], c.src, c.alt),
    visual('table', `pfh-c-${c.id}-info`, [5, y, 11, 5], {
      title: c.name,
      data: {
        columns: [
          { key: 'status', label: 'Status', display: 'pill' },
          { key: 'balance', label: 'Balance', format: eur, align: 'right' },
          { key: 'number', label: 'Card number' },
          { key: 'holder', label: 'Card holder' },
          { key: 'expires', label: 'Expires' },
        ],
        rows: [{ status: c.status, balance: c.balance, number: c.number, holder: c.holder, expires: c.expires }],
      },
      config: { density: 'comfortable', striped: false },
      style: c.id === 'ember' ? SELECTED : {},
    }),
  ];
}

